'use strict';
function performanceBadge(c) { return badge(P.labels[c.state],c.state==='deviation'?'amber':['clean','authorized','tolerance'].includes(c.state)?'green':'blue'); }
function performanceButton(c) { return button('Regra e evidências','perf-control',`data-control="${esc(c.id)}"`,'text small'); }
function performanceDetailView(op) {
  const r=P.evaluate(op); if(!r.requested)return outside('performance');
  const groups=[...new Set(r.checks.map(c=>c.group))];
  return `<section class="conclusion ${r.status}"><div><h2>${r.deviations.length?`${r.deviations.length} controles com desvio para esclarecer`:r.complete?'Condições verificadas, sem desvio':'Performance com cobertura parcial'}</h2><p>${r.deviations.length?'Compare cada compromisso com o realizado e confira as fontes antes de atribuir uma causa.':'Os controles sem referência, regra ou evidência permanecem inconclusivos.'}</p><p class="small muted">${r.evaluated.length}/${r.applicable.length} controles aplicáveis verificados · ${r.ignored.length} não aplicável · ${r.missing.length} com fonte ou regra pendente · ${r.pending.length} aguardando realizado.</p></div>${r.deviations.length?button('Revisar pedido de esclarecimento','communication','','primary'):button('Ver fontes pendentes','perf-missing','','primary')}</section>
  ${r.deviations.length?`<section class="panel"><div class="panel-head"><h2>Desvios que pedem esclarecimento</h2></div><div class="panel-body perf-deviations">${r.deviations.map(c=>`<article><div><strong>${esc(c.name)}</strong><span class="perf-delta">${esc(P.deltaText(c))}${c.percent!==null?' · '+esc(c.percent.toLocaleString('pt-BR'))+'%':''}</span></div><p>Referência ${esc(P.display(c.expected,c))} → realizado ${esc(P.display(c.actual,c))}</p><small>${esc(c.impact)}</small>${performanceButton(c)}</article>`).join('')}</div><div class="section-tail">ETA e trânsito podem representar o mesmo atraso; os dias não são somados. Causa e responsabilidade ainda inconclusivas. Nenhuma pontuação foi atribuída.</div></section>`:''}
  <div class="perf-heading gap"><div><h2>Compromisso × realizado</h2><p class="small muted">23 controles por etapa. A previsão atual e uma mudança de booking não apagam a referência original.</p></div>${button('Ver fontes pendentes','perf-missing','','small')}</div>
  ${groups.map(group=>{const checks=r.checks.filter(c=>c.group===group);return `<details class="panel perf-group" open><summary><strong>${esc(group)}</strong><span>${checks.length} controles · ${checks.filter(c=>c.state==='deviation').length} com desvio</span></summary><div class="table-wrap"><table class="compare-table perf-table"><thead><tr><th>Controle</th><th>Original / vigente</th><th>Realizado / previsão</th><th>Diferença</th><th>Conclusão</th></tr></thead><tbody>${checks.map(c=>`<tr class="${c.state==='deviation'?'flagged':''}"><td><strong>${esc(c.name)}</strong>${performanceButton(c)}</td><td data-label="Original / vigente">${esc(P.display(c.agreed,c))}${c.change?`<small>Vigente: ${esc(P.display(c.expected,c))} · aceite específico</small>`:''}</td><td data-label="Realizado / previsão">${esc(P.display(c.actual,c))}${c.estimated?'<small>Previsão atual · não realizado</small>':''}</td><td data-label="Diferença">${esc(P.deltaText(c))}</td><td>${performanceBadge(c)}${c.note?`<small>${esc(c.note)}</small>`:''}</td></tr>`).join('')}</tbody></table></div></details>`;}).join('')}
  <div class="intro-note gap">Regras, SLAs e evidências desta amostra são demonstrativos. A conclusão produtiva depende do contrato, do DNA versionado e das integrações de documentos e eventos.</div>`;
}
function openPerformanceControl(op,id) {
  const c=P.evaluate(op).checks.find(c=>c.id===id); if(!c)return;
  const field=(label,value)=>`<div class="source-block"><strong>${esc(label)}</strong><p>${esc(value)}</p></div>`;
  openDrawer(c.name,`${performanceBadge(c)}<p class="small muted">${esc(ref(op))} · ${esc(op.reference)} · revisão ${op.version} · DEMO</p>
  ${field('Compromisso original',P.display(c.agreed,c))}${field('Referência vigente',P.display(c.expected,c))}${field(c.estimated?'Previsão atual — não é realizado':'Realizado',P.display(c.actual,c))}${field('Diferença',P.deltaText(c)+(c.percent!==null?' · '+c.percent.toLocaleString('pt-BR')+'%':''))}
  <h3>Regra e evidências</h3>${field('Regra de comparação',c.rule||'Ainda não definida')}${field('Tolerância',c.tolerance===null?'Não definida':c.tolerance+' '+c.unit+' · regra DEMO')}${field('Fonte da referência',c.referenceEvidence||'Não vinculada')}${field('Fonte do realizado',c.actualEvidence||'Não vinculada')}${field('Fontes necessárias',c.source)}${c.scopeEvidence?field('Aplicabilidade',c.scopeEvidence):''}${c.note?field('Limite da conclusão',c.note):''}
  ${c.change?`<h3>Alteração aprovada — escopo deste controle</h3>${field('Condição autorizada',P.display(c.change.value,c))}${field('Aceite',c.change.approver+' · '+date(c.change.date))}${field('Motivo e evidência',c.change.reason+' · '+c.change.evidence)}<p>A autorização deste campo não altera automaticamente datas, trânsito ou outros compromissos.</p>`:''}
  <h3>Causa, impacto e próxima ação</h3>${field('Causa',c.cause)}${field('Responsabilidade',c.responsibility)}${field('Confiança da atribuição',c.confidence)}${field('Impacto',c.impact)}${field('Próxima ação',c.action)}${field('Responsável pela ação e prazo',c.owner+' · '+c.deadline)}
  <details><summary>Critérios de responsabilidade</summary><p>${P.responsibilities.map(esc).join(' · ')}</p><p>Atribuição exige evidência causal; um desvio sozinho não altera a nota do agente.</p></details>
  <h3>Histórico do controle</h3>${c.events?.length?`<ol class="chronology">${c.events.map(e=>`<li><time>${esc(e.at.replace('T',' ').replace('Z',' UTC'))}</time><span>${esc(e.text)}</span></li>`).join('')}</ol>`:''}${c.revisions?.length?`<ol class="chronology">${c.revisions.map(e=>`<li><time>${date(e.at)}</time><span>${esc(e.text)} · ${date(e.value)}</span></li>`).join('')}</ol>`:''}${!c.events?.length&&!c.revisions?.length?'<p class="small muted">Sem histórico adicional vinculado a este controle.</p>':''}<a class="btn small" href="${auditTabUrl(op,'historico')}">Ver trilha da operação</a>`,`${button('Baixar evidência DEMO','download-source',`data-key="perf:${esc(c.id)}"`,'small')}${button('Voltar à comparação','close')}`,{type:'performance-control',opId:op.id});
}
function performanceSources(op) {
  const r=P.evaluate(op);
  return r.checks.map(c=>`<div class="document-link-row"><div><div><strong>${esc(c.name)}</strong><small>${esc(c.source)}</small></div></div><div>${performanceBadge(c)}${performanceButton(c)}</div></div>`).join('');
}
function performanceDocuments(op) {
  const r=P.evaluate(op);
  return `<section class="panel gap"><div class="panel-head"><h2>Compromissos e eventos de performance</h2><span class="small muted">${r.evaluated.length}/${r.applicable.length} aplicáveis verificados</span></div><div class="panel-body">${r.requested?performanceSources(op):'<p>Performance fora do escopo desta operação.</p>'}</div></section>`;
}
function performanceMissing(op) {
  const r=P.evaluate(op);
  openDrawer('Fontes pendentes de performance',`<p>${r.missing.length} controles sem base completa; ${r.pending.length} aguardando realizado. A ausência de fonte não comprova falha do serviço.</p>${[...r.missing,...r.pending].map(c=>`<div class="source-block"><strong>${esc(c.name)}</strong><p>${esc(c.source)}</p><small>${esc(c.state==='pending'?'Aguardar o evento realizado; preservar previsão e referência.':c.limited?c.note:[!c.original||!c.referenceEvidence?'Referência e aceite':null,c.tolerance===null||!c.rule?'Regra / tolerância':null,c.actual===null||!c.actualEvidence?'Evidência do realizado':null].filter(Boolean).join(' · '))}</small>${performanceButton(c)}</div>`).join('')}<p class="small muted">Vínculo, extração e reprocessamento de arquivos ainda não estão integrados. Consulte a fonte necessária em cada controle.</p>`,button('Voltar','close'),{type:'performance-missing',opId:op.id});
}
document.addEventListener('click',event=>{
  const b=event.target.closest('[data-action]');if(!b)return;
  if(b.dataset.action==='perf-control'){event.preventDefault();openPerformanceControl(operation(),b.dataset.control);}
  if(b.dataset.action==='perf-missing'){event.preventDefault();performanceMissing(operation());}
});
